std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> dist(0.0, 1.0);

double totalMass = 0.0;
vec3 totalMomentum(0, 0, 0);

// Calculate total mass and initial momentum
for (size_t i = 0; i < masses.size(); ++i) {
    totalMass += masses[i];
    totalMomentum += velocities[i] * masses[i];
}

// Initialize velocities from Maxwell-Boltzmann distribution
for (size_t i = 0; i < velocities.size(); ++i) {
    double sigma_v = std::sqrt(1.380649e-23 * temperature / masses[i]); // Boltzmann constant in SI units
    // But since we're in reduced units, we use: sigma_v = sqrt(temperature / mass)
    // In reduced units, k_B = 1, so we use temperature directly
    double sigma_v_reduced = std::sqrt(temperature / masses[i]);
    velocities[i] = vec3(dist(gen), dist(gen), dist(gen)) * sigma_v_reduced;
}

// Remove center of mass motion
vec3 comVelocity = totalMomentum / totalMass;
for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] -= comVelocity;
}

// Scale velocities to match target temperature
double currentKE = 0.0;
for (size_t i = 0; i < velocities.size(); ++i) {
    currentKE += 0.5 * masses[i] * velocities[i].lengthSquared();
}

double targetKE = 1.5 * (totalMass * temperature); // For 3D, <KE> = (3/2) * N * k_B * T, but here we use total mass * temperature
// Actually, in reduced units: total kinetic energy should be (3/2) * N * temperature
// But we have: KE = sum_i (0.5 * m_i * v_i^2)
// Target: KE_target = (3/2) * N * temperature
// However, we need to scale based on current KE to target KE
// But note: the correct scaling factor is sqrt( (3/2 * N * T) / currentKE )
// But we don't have N? We have masses.size() as N
size_t N = masses.size();
double scalingFactor = std::sqrt((1.5 * N * temperature) / currentKE);

for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] *= scalingFactor;
}

